import RNA, random, sys, math
target='............((....))...((...((....))..((...((....))...))..((....))...))..((....))....................'
n=len(target)
pairs={}
stack=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

def fold_mfe(seq):
    fc=RNA.fold_compound(seq)
    ss,mfe=fc.mfe()
    return ss,mfe

def fitness(seq):
    ss,_=fold_mfe(seq)
    if ss==target: return 0
    return RNA.bp_distance(ss,target)

# Seed: best structural design (dist=8)
seed=list('AAAAAAAAAAAAGGGAAACCAAACCAAAGGGAAACCAACCAAAGGGAAACCAAAGGAACCGAAAGGAAAGGAAGGGAAACCAAAAAAAAAAAAAAAAAAAA')
COMP={'A':'U','U':'A','G':'C','C':'G'}

def init_random(seed_seq, rng, p=0.3):
    s=list(seed_seq)
    for i in range(n):
        if rng.random()<p:
            if i in pairs:
                j=pairs[i]
                ch=rng.choice(['GC','CG','AU','UA','GU','UG'])
                s[i]=ch[0]; s[j]=ch[1]
            else:
                s[i]=rng.choice('ACGU')
    return ''.join(s)

best=''.join(seed)
bestfit=fitness(best)
sys.stdout.write(f'start fit={bestfit}\n'); sys.stdout.flush()
rng=random.Random(7)
cur=best; curfit=bestfit
T=3.0
for it in range(500000):
    cand=list(cur)
    # mutation: mostly pairs, sometimes unpaired
    if rng.random()<0.6 and pairs:
        i=rng.choice(list(pairs.keys())); j=pairs[i]
        ch=rng.choice(['GC','CG','AU','UA','GU','UG'])
        cand[i]=ch[0]; cand[j]=ch[1]
    else:
        i=rng.randint(0,n-1)
        if i in pairs:
            j=pairs[i]
            ch=rng.choice(['GC','CG','AU','UA','GU','UG'])
            cand[i]=ch[0]; cand[j]=ch[1]
        else:
            cand[i]=rng.choice('ACGU')
    cand=''.join(cand)
    f=fitness(cand)
    if f<=curfit or rng.random()<math.exp(-(f-curfit)/max(T,0.01)):
        cur=cand; curfit=f
    T*=0.99995
    if curfit<bestfit:
        bestfit=curfit; best=cur
        sys.stdout.write(f'it={it} fit={bestfit}\n'); sys.stdout.flush()
        if bestfit==0:
            sys.stdout.write(f'SOLVED\n{best}\n'); sys.stdout.flush()
            break
    if it%10000==0:
