sys.stdout.write(f'FINAL fit={bestfit}\n{best}\n'); sys.stdout.flush()
ss,_=fold_mfe(best)
sys.stdout.write(f'ss={ss}\nmatch={ss==target}\n'); sys.stdout.flush()
